from pathlib import Path
import datetime, hashlib, json, os, re, sys
p=Path(__file__).resolve().parent
start=json.loads((p/'start.json').read_text())
now=datetime.datetime.now(datetime.timezone.utc)
processes=[json.loads(s) for s in (p/'processes.jsonl').read_text().splitlines()]
runs=[];checks=[];duplicates=[]
root=p.parents[3]
known=[(record['path'],json.loads((root/record['path']).read_text())) for record in json.loads((p/'starting-frontier.json').read_text())]
for name in ['baseline','semantic-v2','shallow-v1','shallow-v2','semantic-v3']:
 d=p/name
 if not (d/'receipt.json').exists():continue
 receipt=json.loads((d/'receipt.json').read_text())
 log=(d/'progress.log').read_text() if (d/'progress.log').exists() else ''
 iteration_matches=re.findall(r'iterations=(\d+)',log)
 checkpoints=receipt['checkpoints']
 for item in checkpoints:
  candidate=json.loads(Path(item['path']).read_text())
  matches=[path for path,c in known if c==candidate]
  duplicates.append({'candidate':item['path'],'identical_start_paths':matches,'structural_duplicate':bool(matches)})
  for checker in ['primary','second']:
   if isinstance(item.get(checker),dict):checks.append(item[checker].get('verification_seconds',0))
 runs.append({'name':name,'method':receipt['method'],'seed':receipt['seed'],'receipt_status':receipt['status'],'effective_process_status':('terminated by global-deadline supervisor; raw receipt retained as written' if name=='semantic-v3' and sys.argv[1:]==['complete'] else receipt['status']),'last_logged_iterations':int(iteration_matches[-1]) if iteration_matches else None,'final_log_line':log.splitlines()[-1] if log.splitlines() else None,'checkpoint_coordinates':[[x['XOR'],x['depth']] for x in checkpoints],'checkpoint_count':len(checkpoints),'receipt_path':str(d.relative_to(p)/'receipt.json'),'stop_reason':('adaptive stop: colder sharing-biased method selected after high-temperature cycles failed to improve97' if name=='shallow-v1' else ('global session deadline' if name=='semantic-v3' and sys.argv[1:] == ['complete'] else receipt['status']))})
submissions=[]
for f in sorted((p/'submissions').glob('*.json')) if (p/'submissions').exists() else []:
 submissions.append({'path':str(f.relative_to(p)),'sha256':hashlib.sha256(f.read_bytes()).hexdigest()})
summary={'session_id':start['id'],'instance':start['instance'],'issued_at':start['issued_at'],'budget_started_at':start['issued_at'],'agent_start_time_independently_instrumented':None,'first_search_process_started_at':processes[0]['started_at'] if processes else None,'hard_deadline':start['deadline'],'summary_written_at':now.isoformat(),'ended_at':processes[-1]['ended_at'] if sys.argv[1:]==['complete'] and processes else None,'search_ended_at':processes[-1]['ended_at'] if sys.argv[1:]==['complete'] and processes else None,'agent_summary_end_at':now.isoformat() if sys.argv[1:]==['complete'] else None,'elapsed_from_issued_seconds':((datetime.datetime.fromisoformat(processes[-1]['ended_at']) if sys.argv[1:]==['complete'] and processes else now)-datetime.datetime.fromisoformat(start['issued_at'])).total_seconds(),'receipt_cleanup_seconds_after_search':(now-datetime.datetime.fromisoformat(processes[-1]['ended_at'])).total_seconds() if sys.argv[1:]==['complete'] and processes else None,'status':'complete' if sys.argv[1:]==['complete'] else 'checkpoint','stop_reason':'global 1200-second session deadline; search supervised by budget_run.py' if sys.argv[1:]==['complete'] else 'search still in progress','seed':start['seed'],'seed_derivations':'seed-log.json','initial_frontier_sha256':hashlib.sha256((p/'starting-frontier.json').read_bytes()).hexdigest(),'runs':runs,'search_process_attempts':len(processes),'source_versions_attempted':['search.cpp','search-v2.cpp','shallow.cpp','shallow-v2.cpp','search-v3.cpp'],'trusted_checkpoint_checker_invocations':2*sum(x['checkpoint_count'] for x in runs),'trusted_start_validation_invocations':6*len(runs),'trusted_start_validation_timing':'not separately instrumented; within wrapper process CPU/wall','trusted_cli_submission_checks':sum(len(json.loads(line)['checks']) for line in (p/'submission-checks.jsonl').read_text().splitlines()) if (p/'submission-checks.jsonl').exists() else 0,'internal_search_tests':'Semantic candidates are checked in core before frontier offers; each shallow initialization is materialized and checked. These are internal invariants, not independent trusted-checker evaluations. Exact invocation count unavailable.','proposals':submissions,'new_pareto_points_proposed':len(submissions),'confirmed_novel_points':0,'novelty_status':'No new point emitted so far; correctness and novelty are separate. Known prior frontier remains (88,5),(90,4),(97,3). Unknown-depth89-XOR comparator retained.','invalid_submissions':0,'known_structural_duplicate_emissions':sum(x['structural_duplicate'] for x in duplicates),'search_emissions_are_known_prior_duplicates':not submissions,'process_cpu_seconds':sum(x['cpu_seconds'] for x in processes),'process_wall_seconds':sum(x['wall_seconds'] for x in processes),'process_timing_scope':'Supervised child process totals include compilation and wrappers; core timing and operation counts are in per-run logs.','known_checkpoint_checker_seconds':sum(checks),'costs_unavailable':{'model_token_usage':None,'model_monetary_cost':None,'agent_reasoning_cpu_seconds':None,'preparation_costs':None},'source_files':{str(f.relative_to(p)):hashlib.sha256(f.read_bytes()).hexdigest() for f in sorted(p.iterdir()) if f.suffix in ['.cpp','.py']},'limitations':['Heuristic bounded searches do not prove optimality or absence of smaller circuits.','Depth3 specialization searches homogeneous XOR-only depth3 circuits; affine NOT choices are not searched.','No upstream optimizer executed, no installs or remote writes, no other sessions read.','Root independently adjudicates any submitted proposal.']}
(p/'duplicate-evidence.json').write_text(json.dumps(duplicates,indent=2)+'\n')
t=p/'session-summary.json.tmp';t.write_text(json.dumps(summary,indent=2)+'\n');os.replace(t,p/'session-summary.json')
print(json.dumps({'status':summary['status'],'ended_at':summary['ended_at'],'process_cpu_seconds':summary['process_cpu_seconds'],'proposals':len(submissions)}))
